/**
 * Commerce Kit - storefront client (mock mode, Shipper-managed)
 *
 * SHIPPER_COMMERCE_MODE mock
 *
 * DO NOT EDIT: this file is generated by Shipper. It exposes the SAME hooks as
 * the live version — `useLiveProducts`, `useLiveProduct`, `useCart`,
 * `useCheckout` — so you can build the whole storefront on top of it right now.
 * In this mock mode there is no backend yet: `useLiveProducts` returns an empty
 * catalog (so fall back to your seed data in src/data/products.ts), the cart is
 * fully functional (localStorage), and checkout runs a demo redirect to the
 * success page. When you Enable Shipper Cloud, Shipper swaps this file for the
 * live version (real products + real Stripe checkout) — you do NOT change any
 * storefront code. Build the cart UI on top of `useCart()`; never roll your own
 * cart store.
 */
import { useState, useSyncExternalStore } from "react";

export interface LiveProduct {
  id: string;
  name: string;
  /** Price in major units (e.g. dollars). */
  price: number;
  description?: string;
  category?: string;
  imageUrl?: string;
}

/** One line in the cart passed to checkout. */
export interface CheckoutItem {
  productId: string;
  quantity: number;
}

/**
 * Mock mode: there is no backend catalog yet, so this returns an empty list.
 * Fall back to your seed data in src/data/products.ts when `products` is empty.
 * After Enable Shipper Cloud this reads the merchant's real live catalog.
 */
export function useLiveProducts(): {
  products: LiveProduct[] | undefined;
  isLoading: boolean;
} {
  return { products: [], isLoading: false };
}

/** Mock mode: no backend product by id yet — fall back to your seed by id. */
export function useLiveProduct(_id: string): {
  product: LiveProduct | null | undefined;
  isLoading: boolean;
} {
  return { product: null, isLoading: false };
}

/**
 * One line in the managed cart. Prices are in MAJOR units (dollars) for display
 * only — checkout re-resolves prices server-side from the live catalog, so a
 * tampered price here can never affect what the customer is charged.
 */
export interface CartItem {
  productId: string;
  name: string;
  price: number;
  imageUrl?: string;
  quantity: number;
}

// A single shared cart store (module-level, not per-component) so the header
// badge, cart page and checkout always read the same state. Persisted to
// localStorage and synced across tabs. Read it through useCart().
const CART_STORAGE_KEY = "shipper_cart_v1";
const EMPTY_CART: CartItem[] = [];

function loadCart(): CartItem[] {
  if (typeof window === "undefined") return EMPTY_CART;
  try {
    const raw = window.localStorage.getItem(CART_STORAGE_KEY);
    if (!raw) return EMPTY_CART;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return EMPTY_CART;
    return parsed.filter(
      (i): i is CartItem =>
        i &&
        typeof i.productId === "string" &&
        typeof i.name === "string" &&
        typeof i.price === "number" &&
        typeof i.quantity === "number",
    );
  } catch {
    return EMPTY_CART;
  }
}

let cartItems: CartItem[] = loadCart();
const cartListeners = new Set<() => void>();

function emitCart(): void {
  cartListeners.forEach((l) => l());
}

function setCart(next: CartItem[]): void {
  cartItems = next;
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cartItems));
    } catch {
      /* ignore quota/serialization errors */
    }
  }
  emitCart();
}

if (typeof window !== "undefined") {
  window.addEventListener("storage", (e) => {
    if (e.key === CART_STORAGE_KEY) {
      cartItems = loadCart();
      emitCart();
    }
  });
}

// Managed guarantee: when the shopper lands on the checkout success page — the
// full-page redirect Stripe performs after a completed payment (and the demo
// redirect before Stripe is connected) — clear the cart, so a paid order never
// leaves items behind even if the success page's own code forgets to. Runs once
// at import time on that page's fresh load.
if (typeof window !== "undefined") {
  const path = window.location.pathname;
  if (
    path.endsWith("/checkout/success") ||
    path.endsWith("/checkout/success/")
  ) {
    setCart(EMPTY_CART);
  }
}

function subscribeCart(listener: () => void): () => void {
  cartListeners.add(listener);
  return () => {
    cartListeners.delete(listener);
  };
}

export interface UseCart {
  items: CartItem[];
  /** Add a product (or increment its quantity if already in the cart). */
  addItem: (item: Omit<CartItem, "quantity">, quantity?: number) => void;
  removeItem: (productId: string) => void;
  /** Set an exact quantity; a quantity <= 0 removes the line. */
  updateQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  /** Total number of units across all lines (use for the header badge). */
  itemCount: number;
  /** Sum of price * quantity in major units (dollars). */
  subtotal: number;
}

/**
 * The managed shopping cart. Shared across every component that calls it, so the
 * add-to-cart button, header badge, cart page and checkout stay in sync
 * automatically. Build your cart UI on top of this — do not roll your own store.
 */
export function useCart(): UseCart {
  const items = useSyncExternalStore(
    subscribeCart,
    () => cartItems,
    () => EMPTY_CART,
  );

  const addItem = (item: Omit<CartItem, "quantity">, quantity = 1): void => {
    if (quantity <= 0) return;
    const existing = cartItems.find((i) => i.productId === item.productId);
    if (existing) {
      setCart(
        cartItems.map((i) =>
          i.productId === item.productId
            ? { ...i, ...item, quantity: i.quantity + quantity }
            : i,
        ),
      );
    } else {
      setCart([...cartItems, { ...item, quantity }]);
    }
  };

  const removeItem = (productId: string): void =>
    setCart(cartItems.filter((i) => i.productId !== productId));

  const updateQuantity = (productId: string, quantity: number): void => {
    if (quantity <= 0) {
      setCart(cartItems.filter((i) => i.productId !== productId));
      return;
    }
    setCart(
      cartItems.map((i) =>
        i.productId === productId ? { ...i, quantity } : i,
      ),
    );
  };

  const clearCart = (): void => setCart(EMPTY_CART);

  const itemCount = items.reduce((n, i) => n + i.quantity, 0);
  const subtotal = items.reduce((sum, i) => sum + i.price * i.quantity, 0);

  return {
    items,
    addItem,
    removeItem,
    updateQuantity,
    clearCart,
    itemCount,
    subtotal,
  };
}

/**
 * Mock checkout (no backend yet). Simulates a demo order by sending the shopper
 * to the success page — the SAME UX as live, so wiring the button to
 * `checkout()` works before AND after Shipper Cloud. The success page clears
 * the cart (via useCart().clearCart()). Enabling Shipper Cloud + connecting
 * Stripe swaps this for a real Stripe Checkout Session with zero storefront
 * changes.
 */
export function useCheckout(): {
  checkout: (items?: CheckoutItem[]) => Promise<void>;
  isRedirecting: boolean;
  checkoutReady: boolean | undefined;
  shippingFee: number | undefined;
  freeShippingThreshold: number | null | undefined;
  shippingZones: Array<{ label: string; fee: number }> | undefined;
} {
  const [isRedirecting, setIsRedirecting] = useState(false);

  const checkout = async (_items?: CheckoutItem[]) => {
    if (cartItems.length === 0) return;
    setIsRedirecting(true);
    if (typeof window !== "undefined") {
      window.location.href = window.location.origin + "/checkout/success?demo=1";
    }
  };

  // Mock mode: the demo checkout always works, so the Pay button stays active.
  // No merchant shipping settings exist yet — show "calculated at checkout".
  return {
    checkout,
    isRedirecting,
    checkoutReady: true,
    shippingFee: undefined,
    freeShippingThreshold: undefined,
    shippingZones: undefined,
  };
}
